// fsmSentIsIoPending reports whether the packet awaits asynchronous I/O submission completion.
func fsmSentIsIoPending(s sentStatus) bool {
	return (uint16(1)<<uint(s))&fsmSentMaskIoPending != 0
}

// fsmSentIsResolved reports whether the packet has reached a post-emission resolution state.
func fsmSentIsResolved(s sentStatus) bool {
	return (uint16(1)<<uint(s))&fsmSentMaskResolved != 0
}

var fsmSentValidNext = [8]uint16{
	0: 0x000f, // RESERVED
	1: 0x000e, // SUBMITTED
	2: 0x0074, // EMITTED
	3: 0x0088, // BURNED
	4: 0x0090, // ACKED
	5: 0x00b0, // LOST
	6: 0x00c0, // ABANDONED
	7: 0x0081, // UNUSED
}

// fsmSentCanTransition reports in O(1) whether transitioning from -> to is permitted by the verified SentPacket FSM.
func fsmSentCanTransition(from, to sentStatus) bool {
	return uint(from) < 8 && (uint16(1)<<uint(to))&fsmSentValidNext[from] != 0
}

