// fsmParkStep evaluates the total transition table for (parkSt, event) in O(1) with zero allocations.
func fsmParkStep(s parkSt, ev uint8) fsmStepResult {
	if uint(s) >= 5 || uint(ev) >= 6 {
		return fsmStepResult{next: uint8(s), disp: fsmDispInvalidState}
	}
	return fsmParkTable[s][ev]
}

// ---------------------------------------------------------------------------
// ECNValidation FSM (GRT/1.1 Section 15.4)
// ---------------------------------------------------------------------------

const (
	fsmECN_EV_THREE_CONSISTENT_MARKS_ACKED uint8 = 0
	fsmECN_EV_INVALID_COUNTER_OR_MIGRATION uint8 = 1
)

const (
	fsmECN_ActEnableSteadyECT0 uint16 = 0x0001
	fsmECN_ActDisableECT0      uint16 = 0x0002
)

const (
	fsmECNMaskMarkAllowed uint16 = 0x0003
	fsmECNMaskValidated   uint16 = 0x0002
	fsmECNMaskDisabled    uint16 = 0x0004
)

// fsmECNIsMarkAllowed reports whether ECT(0) marking is permitted on the path (subject to probe cap in UNKNOWN).
func fsmECNIsMarkAllowed(s ecnOutcome) bool {
	return (uint16(1)<<uint(s))&fsmECNMaskMarkAllowed != 0
}

// fsmECNIsValidated reports whether ECN feedback has been validated by three marked acknowledgments.
func fsmECNIsValidated(s ecnOutcome) bool {
	return (uint16(1)<<uint(s))&fsmECNMaskValidated != 0
}

// fsmECNIsDisabled reports whether ECN marking is permanently disabled on the path.
func fsmECNIsDisabled(s ecnOutcome) bool {
	return (uint16(1)<<uint(s))&fsmECNMaskDisabled != 0
}

var fsmECNValidNext = [3]uint16{
	0: 0x0007, // UNKNOWN
	1: 0x0006, // CAPABLE
	2: 0x0004, // BROKEN
}

// fsmECNCanTransition reports in O(1) whether transitioning from -> to is permitted by the verified ECNValidation FSM.
func fsmECNCanTransition(from, to ecnOutcome) bool {
	return uint(from) < 3 && (uint16(1)<<uint(to))&fsmECNValidNext[from] != 0
}

var fsmECNTable = [3][2]fsmStepResult{
	0: { // UNKNOWN
		0: {next: 1, disp: 0, actions: 0x0001},
		1: {next: 2, disp: 0, actions: 0x0002},
	},
	1: { // CAPABLE
		0: {next: 1, disp: 2, actions: 0x0000},
		1: {next: 2, disp: 0, actions: 0x0002},
	},
	2: { // BROKEN
		0: {next: 2, disp: 2, actions: 0x0000},
		1: {next: 2, disp: 2, actions: 0x0000},
	},
}

// fsmECNStep evaluates the total transition table for (ecnOutcome, event) in O(1) with zero allocations.
func fsmECNStep(s ecnOutcome, ev uint8) fsmStepResult {
	if uint(s) >= 3 || uint(ev) >= 2 {
		return fsmStepResult{next: uint8(s), disp: fsmDispInvalidState}
	}
	return fsmECNTable[s][ev]
}

// ---------------------------------------------------------------------------
// TxDataGate Conjunctive Gate (GRT/1.1 Section 22.3)
// ---------------------------------------------------------------------------

const (
	TxDataGate_ConnAppEligible   uint16 = 0x0001 // connection state permits application DATA emission
	TxDataGate_PathBulkEligible  uint16 = 0x0002 // path is ACTIVE with validated 1200B base MTU
	TxDataGate_NotParkedBlocked  uint16 = 0x0004 // no active parking lease/request blocks bulk TX
	TxDataGate_BelowHardKeyLimit uint16 = 0x0008 // active epoch packet number is below 2^32 hard AEAD limit
	TxDataGate_LiveTableAdmitted uint16 = 0x0010 // sent-packet live table is below MaxLiveSent capacity
	TxDataGate_CwndAdmitted      uint16 = 0x0020 // bytes_in_flight + packet_bytes <= cwnd
	TxDataGate_PaceAdmitted      uint16 = 0x0040 // pacing token bucket permits immediate release
	TxDataGate_AmpAdmitted       uint16 = 0x0080 // anti-amplification 3x byte and 3x packet guards permit send
	fsmGateMaskTxData            uint16 = 0x00ff
)

// fsmGateTxData guards emission of ack-eliciting DATA packets carrying application payload.
func fsmGateTxData(flags uint16) bool {
	return flags&fsmGateMaskTxData == fsmGateMaskTxData
}

// ---------------------------------------------------------------------------
// RxCommitGate Conjunctive Gate (GRT/1.1 Section 22.2-22.3)
// ---------------------------------------------------------------------------

const (
	RxCommitGate_ConnKeyBearing           uint16 = 0x0001 // connection is in a key-bearing state and not QUIESCING/DEAD
	RxCommitGate_EpochSlotDecryptEligible uint16 = 0x0002 // matched key slot is INSTALLED or within GRACE window
	RxCommitGate_ReplayFresh              uint16 = 0x0004 // packet number is >= replay floor and not previously committed
	RxCommitGate_AEADVerified             uint16 = 0x0008 // AEAD authentication tag succeeded over canonical header AAD
	RxCommitGate_FramesValid              uint16 = 0x0010 // all frames passed syntactic, state, and flow-control preflight
	RxCommitGate_BufferAdmitted           uint16 = 0x0020 // stream reassembly and control retention quotas admit the transaction
	fsmGateMaskRxCommit                   uint16 = 0x003f
)

// fsmGateRxCommit guards atomic transactional commit of an inbound DATA packet.
func fsmGateRxCommit(flags uint16) bool {
	return flags&fsmGateMaskRxCommit == fsmGateMaskRxCommit
}

// ---------------------------------------------------------------------------
// MigrationCutoverGate Conjunctive Gate (GRT/1.1 Section 17.4-17.7)
// ---------------------------------------------------------------------------

const (
	MigrationCutoverGate_MigrationNegotiated uint16 = 0x0001 // migration is permitted or triggered by authenticated rebinding
	MigrationCutoverGate_CandidateReady1200  uint16 = 0x0002 // candidate path is READY (challenge token + 1200B bidirectional proof)
	MigrationCutoverGate_SequenceMonotonic   uint16 = 0x0004 // migration_seq strictly exceeds highest accepted sequence
	MigrationCutoverGate_CutoverBarrierValid uint16 = 0x0008 // packet number satisfies cutover_pn ordering barrier
	MigrationCutoverGate_NotParked           uint16 = 0x0010 // connection is not in an active sleep lease without wake
	fsmGateMaskMigrationCutover              uint16 = 0x001f
)

// fsmGateMigrationCutover guards promotion of a CANDIDATE path to the connection's ACTIVE path.
func fsmGateMigrationCutover(flags uint16) bool {
	return flags&fsmGateMaskMigrationCutover == fsmGateMaskMigrationCutover
}

// ---------------------------------------------------------------------------
// StreamRetireGate Conjunctive Gate (GRT/1.1 Section 21.1)
// ---------------------------------------------------------------------------

const (
	StreamRetireGate_SlotOccupied     uint16 = 0x0001 // slot is ACTIVE (for initiator RETIRE) or RETIRE_PENDING (for peer RETIRE_ACK)
	StreamRetireGate_SendHalfTerminal uint16 = 0x0002 // send half is nil, SEND_DONE, or SEND_RESET
	StreamRetireGate_RecvHalfTerminal uint16 = 0x0004 // recv half is nil, RECV_DONE, RECV_RESET, or application-stopped
	fsmGateMaskStreamRetire           uint16 = 0x0007
)

// fsmGateStreamRetire guards emission of STREAM_RETIRE or RETIRE_ACK for a stream slot.
func fsmGateStreamRetire(flags uint16) bool {
	return flags&fsmGateMaskStreamRetire == fsmGateMaskStreamRetire
}

// ---------------------------------------------------------------------------
// AmpSendGate Conjunctive Gate (GRT/1.1 Section 6.1, 17.3)
// ---------------------------------------------------------------------------

const (
	AmpSendGate_BytesWithin3x uint16 = 0x0001 // tx_bytes + packet_bytes <= 3 * rx_bytes (or path validated)
	AmpSendGate_PktsWithin3x  uint16 = 0x0002 // tx_pkts + 1 <= 3 * rx_pkts (or path validated)
	fsmGateMaskAmpSend        uint16 = 0x0003
)

// fsmGateAmpSend guards emission on an unvalidated path under the 3x byte and 3x packet anti-amplification rule.
func fsmGateAmpSend(flags uint16) bool {
	return flags&fsmGateMaskAmpSend == fsmGateMaskAmpSend
}

// ---------------------------------------------------------------------------
// KeyCommitGate Conjunctive Gate (GRT/1.1 Section 19.4, 21.2)
// ---------------------------------------------------------------------------

const (
	KeyCommitGate_RefreshStaged      uint16 = 0x0001 // NEXT key slot holds verified STAGED keys for epoch E+1
	KeyCommitGate_EpochNextExact     uint16 = 0x0002 // frame epoch equals active_epoch + 1
	KeyCommitGate_RefreshIDMatched   uint16 = 0x0004 // refresh_id matches the active refresh transaction
	KeyCommitGate_TranscriptMACValid uint16 = 0x0008 // 32-byte commit/confirm HMAC verifies in constant time
	fsmGateMaskKeyCommit             uint16 = 0x000f
)

// fsmGateKeyCommit guards installation of STAGED keys into ACTIVE upon KEY_COMMIT / KEY_CONFIRM.
func fsmGateKeyCommit(flags uint16) bool {
	return flags&fsmGateMaskKeyCommit == fsmGateMaskKeyCommit
}

// ---------------------------------------------------------------------------
// Composite Zero-Allocation Hotpath Gate Evaluators
// ---------------------------------------------------------------------------

// fsmEvalStreamHalvesDone evaluates the Section 21.1 local-halves-terminal
// precondition for slot retirement using generated O(1) bitmask predicates.
func fsmEvalStreamHalvesDone(sendNil bool, sendSt sendState, recvNil bool, recvSt recvState, recvStopped bool) bool {
	sendDone := sendNil || fsmSendIsTerminal(sendSt)
	recvDone := recvNil || fsmRecvIsTerminal(recvSt) || recvStopped
	return sendDone && recvDone
}

// fsmEvalAmpGate evaluates the Section 6.1 / 17.3 3x byte and 3x packet
// anti-amplification gate for unvalidated paths.
func fsmEvalAmpGate(validated bool, txBytes, outBytes, rxBytes, txPkts, rxPkts, ampFactor uint64) bool {
	if validated {
		return true
	}
	var flags uint16
	if txBytes+outBytes <= ampFactor*rxBytes {
		flags |= AmpSendGate_BytesWithin3x
	}
	if txPkts+1 <= ampFactor*rxPkts {
		flags |= AmpSendGate_PktsWithin3x
	}
	return fsmGateAmpSend(flags)
}
